// Writes the HTML shells of the subpages (frontend/pages/<page>.html) from
// frontend/functions/pages-config.js, so that the page list, tabs and search
// entries have one source (spec: backend/md/site/website_structure.md).
// The page scripts (frontend/functions/page-*.js) fill in the articles.
// Generated files: do not edit by hand.

import { writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const esc = (s = '') => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

function article(page, a) {
  return `
    <article id="${a.id}" class="article" data-tab="${esc(a.tab)}"${a.group ? ` data-group="${esc(a.group)}"` : ''}
      data-search="${esc(a.title)}" data-keywords="${esc(a.keywords || '')}">
      <header class="article__header">
        <p class="article__kicker" id="${a.id}-kicker">${esc(page.nav)}</p>
        <h1 class="article__title" id="${a.id}-title">${esc(a.title)}</h1>
        <p class="article__standfirst" id="${a.id}-standfirst">${esc(a.standfirst || '')}</p>
        <div class="article__meta" id="${a.id}-meta">
          <p><span data-kunta-name></span> verrattuna verrokkeihin ja kokoluokkaan</p>
          <share-button target="${a.id}"></share-button>
          <pptx-button target="${a.id}"></pptx-button>
        </div>
      </header>
      <div class="article__content" id="${a.id}-content"><p class="loading">Ladataan…</p></div>
    </article>`;
}

function page(p) {
  return `<!doctype html>
<!-- Generated by backend/functions/build-pages.mjs from frontend/functions/pages-config.js. Do not edit. -->
<html lang="fi">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Tasapaino – ${esc(p.title)}</title>
  <meta name="description" content="${esc(p.standfirst)}">
  <link rel="icon" href="../brand/logos/Kangasala_logo_RGB_color.svg">
  <link rel="stylesheet" href="../styles/base.css">
  <script src="https://cdn.jsdelivr.net/npm/echarts@5.5.1/dist/echarts.min.js"></script>
  <script defer src="../functions/dist/${p.script}"></script>
</head>
<body>
  <site-header active="${p.id}"></site-header>

  <main class="container" data-keywords="${esc(p.keywords)}">
    <header class="page-header">
      <p class="article__kicker"><span data-kunta-name></span> · ${esc(p.nav)}</p>
      <p class="page-header__title">${esc(p.title)}</p>
      <p class="page-header__standfirst">${esc(p.standfirst)}</p>
      <peer-picker></peer-picker>
    </header>
    <site-submenu id="${p.id}-submenu" label="${esc(p.title)}">${p.articles.map((a) => article(p, a)).join('')}
    </site-submenu>
  </main>

  <site-footer></site-footer>
</body>
</html>
`;
}

export async function buildPages(frontend) {
  const { PAGES } = await import(pathToFileURL(join(frontend, 'functions', 'pages-config.js')).href + `?t=${Date.now()}`);
  for (const p of PAGES) await writeFile(join(frontend, 'pages', p.file), page(p), 'utf8');
  return PAGES.length;
}
